-- Summa — Phase 1 Data Warehouse Schema
-- Run once in the Supabase SQL Editor. Idempotent: safe to re-run.
--
-- Architecture (README Part A): one structured table per price-relevant SEC
-- dataset, sourced via edgartools. Only `filings` narrative text rolls off at
-- 30 days; every structured table is retained permanently.
--
-- Security model: the scraper writes with the service_role key (bypasses RLS).
-- The browser reads with the anon key, which gets SELECT-only on every table.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- companies — watchlist metadata. Drives the sidebar list + identity headers.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS companies (
    cik          TEXT PRIMARY KEY,          -- zero-padded 10-digit CIK
        ticker       TEXT,
            name         TEXT,
                sector       TEXT,
                    industry     TEXT,
                        updated_at   TIMESTAMPTZ DEFAULT NOW()
                        );
                        -- Freshness markers driving the staged-cadence scheduler in main.py.
                        --   last_ingested_at — when the company was last *visited* (company-level batch).
                        --   dataset_state    — {dataset: ISO} of the last successful run PER dataset, so
                        --                      heavy slices (fundamentals, 13F) refresh weekly while cheap
                        --                      ones (filings feed) refresh every visit. See DATASET_INTERVALS_H.
                        ALTER TABLE companies ADD COLUMN IF NOT EXISTS last_ingested_at TIMESTAMPTZ;
                        ALTER TABLE companies ADD COLUMN IF NOT EXISTS dataset_state JSONB DEFAULT '{}'::jsonb;

                        -- ---------------------------------------------------------------------------
                        -- financial_facts — tidy (long) XBRL fundamentals. One row per line item per
                        -- period. The frontend pivots line-item × period into the statement table.
                        -- Source: edgartools XBRLS stitched statements (to_dataframe → melt).
                        -- ---------------------------------------------------------------------------
                        CREATE TABLE IF NOT EXISTS financial_facts (
                            id                BIGSERIAL PRIMARY KEY,
                                cik               TEXT        NOT NULL,
                                    ticker            TEXT,
                                        statement         TEXT        NOT NULL,   -- 'income' | 'balance' | 'cashflow'
                                            label             TEXT        NOT NULL,   -- human label, e.g. 'Net sales'
                                                concept           TEXT        NOT NULL,   -- e.g. 'us-gaap_RevenueFrom...'
                                                    standard_concept  TEXT,                   -- normalized, e.g. 'Revenue'
                                                        period_end        DATE        NOT NULL,
                                                            period_type       TEXT        NOT NULL,   -- 'annual' | 'quarterly'
                                                                fiscal_year       INT,
                                                                    value             DOUBLE PRECISION,
                                                                        unit              TEXT        DEFAULT 'USD',
                                                                            display_order     INT,                    -- row order within the statement
                                                                                updated_at        TIMESTAMPTZ DEFAULT NOW(),
                                                                                    UNIQUE (cik, statement, concept, period_end, period_type)
                                                                                    );
                                                                                    CREATE INDEX IF NOT EXISTS idx_ff_cik              ON financial_facts (cik);
                                                                                    CREATE INDEX IF NOT EXISTS idx_ff_cik_stmt_ptype   ON financial_facts (cik, statement, period_type);
                                                                                    CREATE INDEX IF NOT EXISTS idx_ff_period           ON financial_facts (period_end DESC);

                                                                                    -- ---------------------------------------------------------------------------
                                                                                    -- insider_transactions — Form 4 reported trades. Ownership tab net-flow chart.
                                                                                    -- ---------------------------------------------------------------------------
                                                                                    CREATE TABLE IF NOT EXISTS insider_transactions (
                                                                                        id                BIGSERIAL PRIMARY KEY,
                                                                                            cik               TEXT        NOT NULL,   -- subject company CIK
                                                                                                ticker            TEXT,
                                                                                                    accession_number  TEXT        NOT NULL,
                                                                                                        filer_name        TEXT,
                                                                                                            filer_title       TEXT,
                                                                                                                transaction_date  DATE,
                                                                                                                    transaction_code  TEXT,                   -- P, S, A, M, F, G ...
                                                                                                                        acquired_disposed TEXT,                   -- 'A' | 'D'
                                                                                                                            shares            DOUBLE PRECISION,
                                                                                                                                price             DOUBLE PRECISION,
                                                                                                                                    value             DOUBLE PRECISION,       -- shares * price
                                                                                                                                        shares_after      DOUBLE PRECISION,
                                                                                                                                            is_10b5_1         BOOLEAN     DEFAULT FALSE,
                                                                                                                                                filing_url        TEXT,
                                                                                                                                                    filed_at          TIMESTAMPTZ,
                                                                                                                                                        UNIQUE (accession_number, filer_name, transaction_date, transaction_code, shares)
                                                                                                                                                        );
                                                                                                                                                        CREATE INDEX IF NOT EXISTS idx_insider_cik         ON insider_transactions (cik, transaction_date DESC);

                                                                                                                                                        -- ---------------------------------------------------------------------------
                                                                                                                                                        -- institutional_holdings — 13F-HR positions. The literal 13f.info surface.
                                                                                                                                                        -- One row per (subject company, manager, quarter).
                                                                                                                                                        -- ---------------------------------------------------------------------------
                                                                                                                                                        CREATE TABLE IF NOT EXISTS institutional_holdings (
                                                                                                                                                            id                BIGSERIAL PRIMARY KEY,
                                                                                                                                                                cik               TEXT        NOT NULL,   -- subject company CIK
                                                                                                                                                                    ticker            TEXT,
                                                                                                                                                                        period_of_report  DATE        NOT NULL,   -- 13F quarter end
                                                                                                                                                                            manager_name      TEXT        NOT NULL,
                                                                                                                                                                                manager_cik       TEXT,
                                                                                                                                                                                    accession_number  TEXT,
                                                                                                                                                                                        shares            DOUBLE PRECISION,
                                                                                                                                                                                            value             DOUBLE PRECISION,       -- USD position value
                                                                                                                                                                                                pct_of_portfolio  DOUBLE PRECISION,       -- this name as % of manager's 13F
                                                                                                                                                                                                    filed_at          TIMESTAMPTZ,
                                                                                                                                                                                                        UNIQUE (cik, period_of_report, manager_name)
                                                                                                                                                                                                        );
                                                                                                                                                                                                        CREATE INDEX IF NOT EXISTS idx_inst_cik_period     ON institutional_holdings (cik, period_of_report DESC);

                                                                                                                                                                                                        -- ---------------------------------------------------------------------------
                                                                                                                                                                                                        -- beneficial_ownership — SC 13D / 13G stakes ≥5%. Activist timeline.
                                                                                                                                                                                                        -- ---------------------------------------------------------------------------
                                                                                                                                                                                                        CREATE TABLE IF NOT EXISTS beneficial_ownership (
                                                                                                                                                                                                            id                BIGSERIAL PRIMARY KEY,
                                                                                                                                                                                                                cik               TEXT        NOT NULL,
                                                                                                                                                                                                                    ticker            TEXT,
                                                                                                                                                                                                                        accession_number  TEXT        NOT NULL UNIQUE,
                                                                                                                                                                                                                            filer_name        TEXT,
                                                                                                                                                                                                                                schedule          TEXT,                   -- 'SC 13D' | 'SC 13G'
                                                                                                                                                                                                                                    is_activist       BOOLEAN     DEFAULT FALSE,  -- 13D ⇒ activist intent
                                                                                                                                                                                                                                        pct_of_class      DOUBLE PRECISION,
                                                                                                                                                                                                                                            shares            DOUBLE PRECISION,
                                                                                                                                                                                                                                                purpose_excerpt   TEXT,                   -- Item 4 purpose excerpt (≤2000 chars)
                                                                                                                                                                                                                                                    filed_at          TIMESTAMPTZ
                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                    CREATE INDEX IF NOT EXISTS idx_beneficial_cik      ON beneficial_ownership (cik, filed_at DESC);

                                                                                                                                                                                                                                                    -- ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                    -- proposed_sales — Form 144 proposed insider sales. Forward markers.
                                                                                                                                                                                                                                                    -- ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                    CREATE TABLE IF NOT EXISTS proposed_sales (
                                                                                                                                                                                                                                                        id                BIGSERIAL PRIMARY KEY,
                                                                                                                                                                                                                                                            cik               TEXT        NOT NULL,
                                                                                                                                                                                                                                                                ticker            TEXT,
                                                                                                                                                                                                                                                                    accession_number  TEXT        NOT NULL UNIQUE,
                                                                                                                                                                                                                                                                        seller_name       TEXT,
                                                                                                                                                                                                                                                                            relationship      TEXT,
                                                                                                                                                                                                                                                                                shares            DOUBLE PRECISION,
                                                                                                                                                                                                                                                                                    approx_value      DOUBLE PRECISION,
                                                                                                                                                                                                                                                                                        approx_date       DATE,
                                                                                                                                                                                                                                                                                            filed_at          TIMESTAMPTZ
                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                            CREATE INDEX IF NOT EXISTS idx_proposed_cik        ON proposed_sales (cik, filed_at DESC);

                                                                                                                                                                                                                                                                                            -- ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                            -- earnings_events — 8-K Item 2.02 + EX-99.1. Guidance trajectory.
                                                                                                                                                                                                                                                                                            -- ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                            CREATE TABLE IF NOT EXISTS earnings_events (
                                                                                                                                                                                                                                                                                                id                BIGSERIAL PRIMARY KEY,
                                                                                                                                                                                                                                                                                                    cik               TEXT        NOT NULL,
                                                                                                                                                                                                                                                                                                        ticker            TEXT,
                                                                                                                                                                                                                                                                                                            accession_number  TEXT        NOT NULL UNIQUE,
                                                                                                                                                                                                                                                                                                                period            DATE,                   -- fiscal period reported
                                                                                                                                                                                                                                                                                                                    reported_date     DATE,
                                                                                                                                                                                                                                                                                                                        revenue           DOUBLE PRECISION,
                                                                                                                                                                                                                                                                                                                            diluted_eps       DOUBLE PRECISION,
                                                                                                                                                                                                                                                                                                                                net_income        DOUBLE PRECISION,
                                                                                                                                                                                                                                                                                                                                    guidance_action   TEXT,                   -- 'raised'|'lowered'|'maintained'|'withdrawn'|null
                                                                                                                                                                                                                                                                                                                                        guidance_low      DOUBLE PRECISION,
                                                                                                                                                                                                                                                                                                                                            guidance_high     DOUBLE PRECISION,
                                                                                                                                                                                                                                                                                                                                                filed_at          TIMESTAMPTZ
                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                CREATE INDEX IF NOT EXISTS idx_earnings_cik        ON earnings_events (cik, reported_date DESC);

                                                                                                                                                                                                                                                                                                                                                -- ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                -- corporate_events — material 8-K items. Catalyst timeline.
                                                                                                                                                                                                                                                                                                                                                -- ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                CREATE TABLE IF NOT EXISTS corporate_events (
                                                                                                                                                                                                                                                                                                                                                    id                BIGSERIAL PRIMARY KEY,
                                                                                                                                                                                                                                                                                                                                                        cik               TEXT        NOT NULL,
                                                                                                                                                                                                                                                                                                                                                            ticker            TEXT,
                                                                                                                                                                                                                                                                                                                                                                accession_number  TEXT        NOT NULL,
                                                                                                                                                                                                                                                                                                                                                                    event_date        DATE,
                                                                                                                                                                                                                                                                                                                                                                        item_code         TEXT,                   -- '1.01', '5.02', '2.02' ...
                                                                                                                                                                                                                                                                                                                                                                            event_class       TEXT,                   -- 'M&A'|'dilution'|'restatement'|'cyber'|'capital_return'|'exec_change'|'other'
                                                                                                                                                                                                                                                                                                                                                                                summary           TEXT,
                                                                                                                                                                                                                                                                                                                                                                                    filed_at          TIMESTAMPTZ,
                                                                                                                                                                                                                                                                                                                                                                                        UNIQUE (accession_number, item_code)
                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                        CREATE INDEX IF NOT EXISTS idx_corp_events_cik     ON corporate_events (cik, event_date DESC);

                                                                                                                                                                                                                                                                                                                                                                                        -- ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                        -- late_filings — NT 10-K / NT 10-Q notifications. Red flags.
                                                                                                                                                                                                                                                                                                                                                                                        -- ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                        CREATE TABLE IF NOT EXISTS late_filings (
                                                                                                                                                                                                                                                                                                                                                                                            id                BIGSERIAL PRIMARY KEY,
                                                                                                                                                                                                                                                                                                                                                                                                cik               TEXT        NOT NULL,
                                                                                                                                                                                                                                                                                                                                                                                                    ticker            TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                        accession_number  TEXT        NOT NULL UNIQUE,
                                                                                                                                                                                                                                                                                                                                                                                                            nt_form           TEXT,                   -- 'NT 10-K' | 'NT 10-Q'
                                                                                                                                                                                                                                                                                                                                                                                                                subject_form      TEXT,                   -- '10-K' | '10-Q'
                                                                                                                                                                                                                                                                                                                                                                                                                    period            DATE,
                                                                                                                                                                                                                                                                                                                                                                                                                        reason_excerpt    TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                            filed_at          TIMESTAMPTZ
                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                            CREATE INDEX IF NOT EXISTS idx_late_cik            ON late_filings (cik, filed_at DESC);

                                                                                                                                                                                                                                                                                                                                                                                                                            -- ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                            -- securities_offerings — S-3 / 424B dilution events.
                                                                                                                                                                                                                                                                                                                                                                                                                            -- ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                            CREATE TABLE IF NOT EXISTS securities_offerings (
                                                                                                                                                                                                                                                                                                                                                                                                                                id                BIGSERIAL PRIMARY KEY,
                                                                                                                                                                                                                                                                                                                                                                                                                                    cik               TEXT        NOT NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                        ticker            TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                            accession_number  TEXT        NOT NULL UNIQUE,
                                                                                                                                                                                                                                                                                                                                                                                                                                                form              TEXT,                   -- 'S-3' | '424B5' ...
                                                                                                                                                                                                                                                                                                                                                                                                                                                    offering_type     TEXT,                   -- 'shelf'|'secondary'|'ATM'|'convertible'|'other'
                                                                                                                                                                                                                                                                                                                                                                                                                                                        amount            DOUBLE PRECISION,       -- USD
                                                                                                                                                                                                                                                                                                                                                                                                                                                            shares            DOUBLE PRECISION,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                filed_at          TIMESTAMPTZ
                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                CREATE INDEX IF NOT EXISTS idx_offerings_cik       ON securities_offerings (cik, filed_at DESC);

-- ---------------------------------------------------------------------------
-- ipos — active IPO pipeline. GLOBAL (not watchlist-scoped): one row per
-- IPO-lifecycle filing across the whole market (S-1/F-1 registration, S-1/A
-- amendment, 424B pricing, RW withdrawal). Written by ipo_extractor's global
-- pass; the frontend groups rows by issuer to show one card per IPO. Pruned to
-- the recent window by cleanup.py (prune_old_ipos).
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ipos (
    id                BIGSERIAL PRIMARY KEY,
    accession_number  TEXT        NOT NULL UNIQUE,
    cik               TEXT        NOT NULL,
    company_name      TEXT,
    ticker            TEXT,
    form              TEXT,                   -- 'S-1' | 'S-1/A' | 'F-1' | '424B4' | 'RW' ...
    status            TEXT,                   -- 'filed' | 'updated' | 'priced' | 'withdrawn'
    is_spac           BOOLEAN,
    price             DOUBLE PRECISION,       -- offering price per share (priced only)
    shares            DOUBLE PRECISION,       -- shares offered
    proceeds          DOUBLE PRECISION,       -- gross proceeds, USD
    offering_type     TEXT,
    filing_url        TEXT,
    filed_at          TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_ipos_cik      ON ipos (cik, filed_at DESC);
CREATE INDEX IF NOT EXISTS idx_ipos_filed_at ON ipos (filed_at DESC);
CREATE INDEX IF NOT EXISTS idx_ipos_status   ON ipos (status);

-- ---------------------------------------------------------------------------
-- company_news — per-company headlines from Google News RSS. The SECOND (and
-- only other) non-SEC source alongside daily_prices: Google News' keyless,
-- free RSS search feed (news_ingest.py). One row per article per company.
-- Powers the News view + per-company headline strip. Pruned to a rolling
-- 30-day window by cleanup.py (prune_old_news) — it's a recent-headlines
-- surface, not an archive. Degrades gracefully: if empty, the News UI is hidden.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS company_news (
    id            BIGSERIAL PRIMARY KEY,
    cik           TEXT        NOT NULL,
    ticker        TEXT,
    company_name  TEXT,
    guid          TEXT        NOT NULL,   -- stable per-article id from the RSS <guid> (falls back to link)
    title         TEXT,
    link          TEXT,
    source        TEXT,                   -- publisher name (RSS <source>)
    summary       TEXT,                   -- RSS <description>, stripped of markup (<= 2000 chars)
    published_at  TIMESTAMPTZ,
    created_at    TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE (cik, guid)
);
-- Trader-importance score + category, computed at ingest by news_score.py. Lets the
-- UI surface the important headlines per company first and gate the Discord alerts.
ALTER TABLE company_news ADD COLUMN IF NOT EXISTS importance INT DEFAULT 0;
ALTER TABLE company_news ADD COLUMN IF NOT EXISTS category   TEXT;
CREATE INDEX IF NOT EXISTS idx_news_cik       ON company_news (cik, published_at DESC);
CREATE INDEX IF NOT EXISTS idx_news_published ON company_news (published_at DESC);
CREATE INDEX IF NOT EXISTS idx_news_cik_imp   ON company_news (cik, importance DESC, published_at DESC);

-- Realtime: stream new headlines to the browser the instant the pipeline inserts
-- them (the News view subscribes via subscribeNews). Supabase Realtime is on the
-- free tier. Adding a table to the publication twice errors, so guard it. INSERT
-- payloads carry the full new row by default (no REPLICA IDENTITY change needed).
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_publication_tables
        WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'company_news'
    ) THEN
        EXECUTE 'ALTER PUBLICATION supabase_realtime ADD TABLE company_news';
    END IF;
END $$;

-- ---------------------------------------------------------------------------
-- market_news — the curated, market-wide "Top Intelligence" feed. GLOBAL (not
-- watchlist-scoped): market-mover headlines pulled from free RSS sources (SEC
-- press releases, the Federal Reserve, the FDA, PR Newswire) by
-- market_news_ingest.py, scored for trader-importance and kept ONLY above a
-- strict threshold — so this table stays small and high-signal by construction.
-- Pruned to a rolling 30-day window by cleanup.py (prune_old_market_news).
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS market_news (
    id            BIGSERIAL PRIMARY KEY,
    guid          TEXT        NOT NULL UNIQUE,   -- stable per-article id (RSS <guid>, falls back to link)
    source        TEXT,                          -- 'SEC' | 'Federal Reserve' | 'FDA' | 'PR Newswire' ...
    category      TEXT,                          -- classified: 'Fed' | 'FDA' | 'Legal' | 'Deal' | 'Earnings' ...
    importance    INT         DEFAULT 0,         -- computed market-mover score (higher = more important)
    title         TEXT,
    link          TEXT,
    summary       TEXT,                          -- stripped of markup (<= 2000 chars)
    published_at  TIMESTAMPTZ,
    created_at    TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_mktnews_published  ON market_news (published_at DESC);
CREATE INDEX IF NOT EXISTS idx_mktnews_importance ON market_news (importance DESC, published_at DESC);

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_publication_tables
        WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'market_news'
    ) THEN
        EXECUTE 'ALTER PUBLICATION supabase_realtime ADD TABLE market_news';
    END IF;
END $$;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- filings — narrative filings feed. Text sections roll off at 30 days
                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- (cleanup.py); the metadata row is retained. Realtime feed reads this.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                CREATE TABLE IF NOT EXISTS filings (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    id                BIGSERIAL PRIMARY KEY,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        accession_number  TEXT        NOT NULL UNIQUE,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cik               TEXT        NOT NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ticker            TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    company_name      TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        form_type         TEXT        NOT NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            filed_at          TIMESTAMPTZ,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                period_of_report  DATE,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    filing_url        TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        -- Cleaned narrative sections (≤8000 chars each; raw HTML never stored).
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- Rolled off at 30 days by cleanup.py.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                section_business        TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    section_risk_factors    TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        section_mda             TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            created_at        TIMESTAMPTZ DEFAULT NOW()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            CREATE INDEX IF NOT EXISTS idx_filings_cik         ON filings (cik);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            CREATE INDEX IF NOT EXISTS idx_filings_form        ON filings (form_type);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            CREATE INDEX IF NOT EXISTS idx_filings_filed_at    ON filings (filed_at DESC);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- daily_prices — end-of-day OHLCV bars. The ONLY non-SEC dataset: sourced from
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- Stooq's free, keyless daily CSV (price_ingest.py). Powers the price KPIs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- the company price chart, and the "% off 52-wk high" signal. EOD, not realtime.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- Degrades gracefully: if empty, all price UI/signals simply don't render.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            CREATE TABLE IF NOT EXISTS daily_prices (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                id          BIGSERIAL PRIMARY KEY,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cik         TEXT        NOT NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ticker      TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            date        DATE        NOT NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                open        DOUBLE PRECISION,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    high        DOUBLE PRECISION,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        low         DOUBLE PRECISION,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            close       DOUBLE PRECISION,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                volume      DOUBLE PRECISION,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    UNIQUE (cik, date)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    CREATE INDEX IF NOT EXISTS idx_prices_cik_date    ON daily_prices (cik, date DESC);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- ===========================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- Reference data — small, slowly-changing context tables. Populated by the
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- backend (SIC mapping + curated seeds, later LLM). Read once per session by the
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- frontend and matched client-side; never joined per row. See
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- backend/docs/REFERENCE_DATA_SCOPE.md.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- ===========================================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- Per-company industry classification + strategic narrative.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    CREATE TABLE IF NOT EXISTS company_profiles (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cik         TEXT PRIMARY KEY REFERENCES companies(cik),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            sector      TEXT,            -- broad bucket (from SEC SIC, normalized)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                industry    TEXT,            -- specific line of business
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    thesis      TEXT,            -- high-level strategic picture (1-2 sentences)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        source      TEXT,            -- 'sic' | 'seed' | 'llm:10-K'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            updated_at  TIMESTAMPTZ DEFAULT NOW()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- Forward-looking themes / next-trend bets, with plain-language context.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            CREATE TABLE IF NOT EXISTS company_themes (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cik         TEXT REFERENCES companies(cik),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    name        TEXT,            -- e.g. "Dojo"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        note        TEXT,            -- what it is + why it matters
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            rank        INT,             -- display order
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                source      TEXT,            -- 'seed' | 'llm:10-K'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    PRIMARY KEY (cik, name)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    CREATE INDEX IF NOT EXISTS idx_company_themes_cik ON company_themes (cik);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- Investor / manager context registry (global lookup, not keyed to a company).
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    CREATE TABLE IF NOT EXISTS entities (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        match_key   TEXT PRIMARY KEY,  -- lowercase substring that identifies the filer
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            kind        TEXT,              -- 'index' | 'active' | 'bank' | 'activist' | 'value'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                note        TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    source      TEXT,              -- 'seed' | 'llm'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        updated_at  TIMESTAMPTZ DEFAULT NOW()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        -- Dynamic watchlist / ingest queue. The frontend may INSERT here (the single
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        -- anon-write exception) to request a new company; the backend reads it, ingests,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        -- and flips status to 'ingested'. Keeps the pipeline scalable without code edits.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        CREATE TABLE IF NOT EXISTS watchlist (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cik         TEXT PRIMARY KEY,          -- zero-padded 10-digit CIK
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ticker      TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    name        TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        status      TEXT DEFAULT 'queued',     -- 'queued' | 'ingested'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            added_at    TIMESTAMPTZ DEFAULT NOW()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- ===========================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- Row Level Security — anon gets SELECT-only on every table; service_role
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- (scraper) bypasses RLS entirely. Idempotent.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- ===========================================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            DO $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            DECLARE t TEXT;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            BEGIN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                FOREACH t IN ARRAY ARRAY[
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'companies','financial_facts','insider_transactions','institutional_holdings',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'beneficial_ownership','proposed_sales','earnings_events','corporate_events',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'late_filings','securities_offerings','filings','daily_prices',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'company_profiles','company_themes','entities','ipos','company_news','market_news'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ] LOOP
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    EXECUTE format('REVOKE ALL ON %I FROM anon, authenticated', t);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            EXECUTE format('GRANT SELECT ON %I TO anon', t);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    EXECUTE format('DROP POLICY IF EXISTS "anon read %1$s" ON %1$I', t);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            EXECUTE format('CREATE POLICY "anon read %1$s" ON %1$I FOR SELECT TO anon USING (true)', t);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                END LOOP;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                END $$;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- Watchlist is the one anon-writable table: the frontend may SELECT and INSERT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- (queue a company), but not UPDATE or DELETE. The backend (service_role) flips
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- status. Idempotent.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ALTER TABLE watchlist ENABLE ROW LEVEL SECURITY;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                REVOKE ALL ON watchlist FROM anon, authenticated;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                GRANT SELECT, INSERT ON watchlist TO anon;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                DROP POLICY IF EXISTS "anon read watchlist" ON watchlist;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                CREATE POLICY "anon read watchlist" ON watchlist FOR SELECT TO anon USING (true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                DROP POLICY IF EXISTS "anon insert watchlist" ON watchlist;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                CREATE POLICY "anon insert watchlist" ON watchlist FOR INSERT TO anon WITH CHECK (true);

-- ===========================================================================
-- company_summary — ONE small precomputed row per company. Powers the
-- watchlist-wide surfaces (Overview table, Momentum Scanner) so the frontend
-- reads a single bounded, paginated query instead of every company's full price
-- history. This is what lets those views scale to any watchlist size: cost is
-- O(companies) tiny rows, not O(companies x ~252 price rows). Recomputed by the
-- backend (summary_ingest.py) on each company visit. Idempotent.
-- ===========================================================================
CREATE TABLE IF NOT EXISTS company_summary (
    cik              TEXT PRIMARY KEY REFERENCES companies(cik),
    ticker           TEXT,
    last_close       NUMERIC,
    as_of            DATE,
    chg_1d           NUMERIC,        -- % vs the prior close
    ret_ytd          NUMERIC,
    pct_off_high     NUMERIC,        -- % below the trailing 52-week high (<= 0)
    rsi14            NUMERIC,
    pct_from_50      NUMERIC,        -- % of last close above/below the 50-day SMA
    pct_from_200     NUMERIC,
    ma_cross         TEXT,           -- 'golden' | 'death' | NULL
    vol_spike        NUMERIC,        -- latest volume / 30-day avg volume
    new_52w_high     BOOLEAN DEFAULT FALSE,
    new_52w_low      BOOLEAN DEFAULT FALSE,
    spark            JSONB,          -- last ~60 closes for the sparkline
    filings_30d      INT DEFAULT 0,
    last_filing_form TEXT,
    last_filing_at   TIMESTAMPTZ,
    net_insider_90d  NUMERIC,        -- net open-market $ (buys - sells), trailing 90d
    cluster_buy      BOOLEAN DEFAULT FALSE,
    updated_at       TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE company_summary ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON company_summary FROM anon, authenticated;
GRANT SELECT ON company_summary TO anon;
DROP POLICY IF EXISTS "anon read company_summary" ON company_summary;
CREATE POLICY "anon read company_summary" ON company_summary FOR SELECT TO anon USING (true);

-- ===========================================================================
-- manager_portfolios — each tracked 13F manager's TOP holdings across ALL
-- stocks (not just the watchlist), plus the quarter-over-quarter MOVE for each
-- position (what they bought vs sold vs exited). Powers the Managers view
-- ("what does Vanguard / BlackRock actually invest in, and what are they
-- buying/selling"). One row per (manager, quarter, security). Bounded and
-- slowly-changing. Written by the global pass in institutional_extractor.py
-- (ingest_manager_portfolios), which reuses the 13F cache the per-company
-- institutional ingest already populates and diffs it against the prior quarter
-- already stored here — no extra EDGAR load. Idempotent.
-- ===========================================================================
CREATE TABLE IF NOT EXISTS manager_portfolios (
    id                BIGSERIAL PRIMARY KEY,
    manager_cik       TEXT        NOT NULL,
    manager_name      TEXT        NOT NULL,   -- curated label (e.g. 'BLACKROCK')
    period_of_report  DATE        NOT NULL,   -- 13F quarter end
    accession_number  TEXT,
    rank              INT,                    -- 1 = largest position that quarter
    cusip             TEXT        NOT NULL,   -- the stable 13F security id
    ticker            TEXT,
    issuer            TEXT,                   -- security/issuer name
    shares            DOUBLE PRECISION,
    value             DOUBLE PRECISION,       -- USD position value
    pct_of_portfolio  DOUBLE PRECISION,       -- value / total 13F value
    -- Quarter-over-quarter move vs the manager's prior 13F (what they did).
    prior_shares      DOUBLE PRECISION,       -- shares held the prior quarter (NULL = not in prior top holdings)
    prior_value       DOUBLE PRECISION,       -- USD value the prior quarter
    share_change      DOUBLE PRECISION,       -- shares - prior_shares (signed)
    action            TEXT,                   -- 'new'|'added'|'trimmed'|'unchanged'|'exited'
    filed_at          TIMESTAMPTZ,
    UNIQUE (manager_cik, period_of_report, cusip)
);
CREATE INDEX IF NOT EXISTS idx_mgrport_mgr ON manager_portfolios (manager_cik, period_of_report DESC, value DESC);

ALTER TABLE manager_portfolios ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON manager_portfolios FROM anon, authenticated;
GRANT SELECT ON manager_portfolios TO anon;
DROP POLICY IF EXISTS "anon read manager_portfolios" ON manager_portfolios;
CREATE POLICY "anon read manager_portfolios" ON manager_portfolios FOR SELECT TO anon USING (true);

-- ===========================================================================
-- reddit_trends — daily snapshot of the most-discussed stock tickers on the
-- big investing subreddits (r/wallstreetbets, r/stocks, r/investing, …).
-- GLOBAL (market-wide, not watchlist-scoped): one ranked top-N snapshot per
-- day, written by ingest/reddit_trends_ingest.py (summa-reddit.yml, daily)
-- from the free keyless ApeWisdom + Tradestie aggregator APIs. Powers the
-- Discord "Reddit Trending Stocks" digest; ~30-day rolling window
-- (cleanup.py prune_old_reddit_trends). Idempotent.
-- ===========================================================================
CREATE TABLE IF NOT EXISTS reddit_trends (
    id               BIGSERIAL PRIMARY KEY,
    trend_date       DATE        NOT NULL,     -- snapshot day (UTC)
    ticker           TEXT        NOT NULL,
    name             TEXT,                     -- company name per the aggregator
    rank             INT,                      -- 1 = most discussed that day
    mentions         INT,                      -- mention/comment count (per source)
    upvotes          INT,                      -- aggregate upvotes (ApeWisdom only)
    rank_change      INT,                      -- vs 24h ago; positive = climbing
    mentions_change  INT,                      -- mentions delta vs 24h ago
    sentiment        TEXT,                     -- 'Bullish' | 'Bearish' (Tradestie WSB)
    sentiment_score  NUMERIC,                  -- signed score behind the label
    source           TEXT,                     -- 'apewisdom:all-stocks' | 'tradestie:wallstreetbets'
    created_at       TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE (trend_date, ticker)
);
CREATE INDEX IF NOT EXISTS idx_reddit_trends_day ON reddit_trends (trend_date DESC, rank ASC);

-- Price context per stored ticker (Yahoo keyless chart endpoint, same source as
-- price_ingest) — lets the Reddit Buzz view + the "high buzz, low price" Discord
-- screen cross-reference chatter with where the stock trades in its 52-week
-- range. Snapshot display data, not a price warehouse (daily_prices remains that).
ALTER TABLE reddit_trends ADD COLUMN IF NOT EXISTS last_price   NUMERIC;  -- live/latest close
ALTER TABLE reddit_trends ADD COLUMN IF NOT EXISTS day_pct      NUMERIC;  -- % vs prior session
ALTER TABLE reddit_trends ADD COLUMN IF NOT EXISTS off_high_pct NUMERIC;  -- % below 52w high (negative)
ALTER TABLE reddit_trends ADD COLUMN IF NOT EXISTS off_low_pct  NUMERIC;  -- % above 52w low (small = near low)
ALTER TABLE reddit_trends ADD COLUMN IF NOT EXISTS is_etf       BOOLEAN;  -- index/ETF chatter, excluded from the value screen
-- Industry labels resolved at ingest (prior stored labels → curated
-- company_profiles → SEC submissions SIC) so market-wide tickers read as
-- companies, not just symbols.
ALTER TABLE reddit_trends ADD COLUMN IF NOT EXISTS sector       TEXT;
ALTER TABLE reddit_trends ADD COLUMN IF NOT EXISTS industry     TEXT;

ALTER TABLE reddit_trends ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON reddit_trends FROM anon, authenticated;
GRANT SELECT ON reddit_trends TO anon;
DROP POLICY IF EXISTS "anon read reddit_trends" ON reddit_trends;
CREATE POLICY "anon read reddit_trends" ON reddit_trends FOR SELECT TO anon USING (true);

-- ===========================================================================
-- congress_trades — congressional (+ executive-branch) STOCK-Act stock-trade
-- disclosures. GLOBAL (market-wide, not watchlist-scoped): written by
-- ingest/congress_trades_ingest.py (summa-congress.yml, ~2×/day) from the free
-- keyless JSON behind Kadoa's open-source Congress Trading Monitor (normalized
-- House Clerk PTR + Senate eFD feeds). One row per disclosed transaction,
-- keyed on the source's stable id; only rows with a resolvable ticker are
-- stored. Powers the Congress view's consensus buys/sells (stocks 2+ members
-- bought/sold in a window); ~400-day rolling window
-- (cleanup.py prune_old_congress_trades). Idempotent.
-- ===========================================================================
CREATE TABLE IF NOT EXISTS congress_trades (
    id               TEXT PRIMARY KEY,          -- source transaction id (stable)
    source_id        TEXT,                      -- 'senate_efd' | 'house_ptr' | …
    branch           TEXT,                      -- 'congress' | 'executive'
    chamber          TEXT,                      -- 'senate' | 'house' | NULL
    party            TEXT,                      -- 'D' | 'R' | 'I' | NULL
    state            TEXT,
    office           TEXT,                      -- e.g. 'U.S. Senator · RI'
    filer_id         TEXT,                      -- stable per-politician key
    filer_name       TEXT,
    ticker           TEXT NOT NULL,
    asset_name       TEXT,
    asset_type       TEXT,
    side             TEXT NOT NULL,             -- 'buy' | 'sell' | 'exchange'
    transaction_type TEXT,                      -- raw label, e.g. 'Sale (Partial)'
    transaction_date DATE NOT NULL,
    filing_date      DATE,
    days_to_file     INT,
    is_late          BOOLEAN,
    owner            TEXT,                      -- 'Self' | 'Spouse' | 'Joint' | …
    amount_low       NUMERIC,                   -- disclosed range, e.g. 15001
    amount_high      NUMERIC,                   -- e.g. 50000
    amount_label     TEXT,                      -- '$15,001 - $50,000'
    doc_url          TEXT,                      -- official disclosure document
    filing_type      TEXT,                      -- 'PTR' | …
    ret_since        NUMERIC,                   -- stock return since the trade (source-computed)
    excess_since     NUMERIC,                   -- return vs the market since the trade
    created_at       TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_congress_trades_txn    ON congress_trades (transaction_date DESC);
CREATE INDEX IF NOT EXISTS idx_congress_trades_ticker ON congress_trades (ticker, transaction_date DESC);

ALTER TABLE congress_trades ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON congress_trades FROM anon, authenticated;
GRANT SELECT ON congress_trades TO anon;
DROP POLICY IF EXISTS "anon read congress_trades" ON congress_trades;
CREATE POLICY "anon read congress_trades" ON congress_trades FOR SELECT TO anon USING (true);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
